package dev.hoi.client.map;

import com.mojang.blaze3d.platform.InputConstants;
import dev.hoi.protocol.ProtocolCommanderHud.*;
import dev.hoi.protocol.ProtocolCommanderOrders;
import java.util.*;
import net.fabricmc.fabric.api.client.gametest.v1.context.ClientGameTestContext;

final class MapCommanderTheatersRenderTest {
    private static final String TEMPLATE_ONE="§H편제 하나§!\n\n§GShift + 클릭§!하여 선택 전환\n보병: 3";
    private static final String TEMPLATE_TWO="§H편제 둘§!\n\n§GShift + 클릭§!하여 선택 전환\n지원 중대: 1";
    static void run(ClientGameTestContext game,int[] size,View source){
        var names=MapCommanderGroupsRenderTest.sourceNames();var commands=new ArrayList<ProtocolCommanderOrders.Command>();var requests=new ArrayList<Open>();var gson=new com.google.gson.Gson();var json=gson.toJsonTree(source).getAsJsonObject();
        for(var item:json.getAsJsonArray("cards")){var card=item.getAsJsonObject();if(!card.get("id").getAsString().equals("A"))continue;var panel=card.getAsJsonObject("panel");panel.add("templateSummaries",gson.toJsonTree(List.of(new TemplateSummary("template/one","unit_hud/infantry",1,TEMPLATE_ONE,List.of("a1")),new TemplateSummary("template/two","unit_hud/infantry",1,TEMPLATE_TWO,List.of("a2")))));int i=0;for(var row:panel.getAsJsonArray("members")){row.getAsJsonObject().addProperty("name",names.get(i));var data=row.getAsJsonObject().getAsJsonObject("data");data.addProperty("orderWarning",i==0?"NO_ORDERS":"INVALID_ORDERS");data.addProperty("orderTooltip",i==0?"§R명령 없음§!":"§R유효하지 않은 명령§!");data.addProperty("coldAcclimatization",i==0?.5:0);data.addProperty("hotAcclimatization",i++==0?0:1);}}
        var base=gson.fromJson(json,View.class);var controls=List.of(new Control("THEATER_SETTINGS","","전구 설정 미지원",false,new Open(Mode.ARMY_TOOLBAR,"THEATER_SETTINGS",List.of("theater/1"))),new Control("THEATER_OFFENSIVE/4/0","","공격 전투",false,new Open(Mode.ARMY_TOOLBAR,"THEATER_OFFENSIVE")),new Control("THEATER_DEFENSIVE/2/1","","방어 전투",false,new Open(Mode.ARMY_TOOLBAR,"THEATER_DEFENSIVE")),new Control("THEATER_ASSIGN","","§G클릭§!하여 전구 선택\n§G우클릭§!하여 배정",true,new Open(Mode.ARMY_TOOLBAR,"THEATER_ASSIGN")),new Control("THEATER_CREATE","","새로운 전구",true,new Open(Mode.ARMY_TOOLBAR,"THEATER_CREATE")));
        var theater=new Theater("theater/1","한국 전구 1",4,List.of("G1","G2"),List.of("A","B","C"),Map.of("A","§R명령 없음§!","B","§R명령 없음§!"),controls);var view=new View(base.country(),base.dimension(),base.branch(),base.cards(),base.wings(),true,List.of(theater));
        game.runOnClient(client->{MapCommanderHud.reset();MapUnitHud.reset();MapCommanderHud.requestObserver=requests::add;MapCommanderOrders.commandObserver=commands::add;MapCommanderOrders.selectionObserver=s->{};MapCommanderHud.accept(view);MapCommanderPanels.select("A",false);MapCommanderOrders.accept(new ProtocolCommanderOrders.Context(UUID.randomUUID().toString(),0,"KOR",view.dimension(),""));});game.waitTicks(2);
        game.runOnClient(client->{var summaries=MapCommanderPanels.hits().stream().filter(h->h.icon().equals("template_summary")).toList();if(summaries.size()!=2||!summaries.get(0).tip().equals(TEMPLATE_ONE)||!summaries.get(1).tip().equals(TEMPLATE_TWO))throw new AssertionError("Same-icon templates must keep distinct source tooltips and selection targets");var before=MapUnitHud.selectedKeys();click(summaries.get(0),InputConstants.MOUSE_BUTTON_RIGHT);if(!MapUnitHud.selectedKeys().equals(before))throw new AssertionError("Template summary right click must preserve selection: before="+before+", after="+MapUnitHud.selectedKeys()+", overlaps="+MapCommanderPanels.hits().stream().filter(h->h.contains(summaries.get(0).x()+summaries.get(0).w()/2.,summaries.get(0).y()+summaries.get(0).h()/2.)).map(h->h.icon()+":"+h.tip()).toList());click(summaries.get(0),InputConstants.MOUSE_BUTTON_LEFT);if(!MapUnitHud.selectedKeys().equals(Set.of("unit/a1")))throw new AssertionError("Template selection merged two templates sharing an icon");});game.waitTicks(2);
        game.getInput().holdKey(o->o.keyShift);game.runOnClient(client->click(hit("template_summary",TEMPLATE_TWO),InputConstants.MOUSE_BUTTON_LEFT));game.getInput().releaseKey(o->o.keyShift);game.waitTicks(2);
        game.runOnClient(client->{if(!MapUnitHud.selectedKeys().equals(Set.of("unit/a1","unit/a2")))throw new AssertionError("Shift must add only the exact second template divisions");var button=hit("change_template_button",null);click(button,InputConstants.MOUSE_BUTTON_RIGHT);if(!requests.isEmpty())throw new AssertionError("Template right click must issue nothing");click(button,InputConstants.MOUSE_BUTTON_LEFT);if(!requests.equals(List.of(new Open(Mode.ARMY_TOOLBAR,"DIVISIONS_TEMPLATE",List.of("unit/a1","unit/a2")))))throw new AssertionError("Template picker must use exact server request");requests.clear();click(hit("theater_settings",null),InputConstants.MOUSE_BUTTON_LEFT);if(!requests.isEmpty()||!commands.isEmpty())throw new AssertionError("Unsupported theater settings must remain disabled");if(MapCommanderPanels.hits().stream().noneMatch(h->h.icon().equals("army_order_warning")&&h.tip().equals("§R명령 없음§!")))throw new AssertionError("Order warning must use authoritative tooltip");var rows=view.cards().stream().filter(c->c.id().equals("A")).findFirst().orElseThrow().panel().members();if(MapCommanderPanels.acclimatizationFrame(rows.get(0).data())!=0||MapCommanderPanels.acclimatizationFrame(rows.get(1).data())!=3||MapCommanderPanels.acclimatizationFrame(null)!=-1)throw new AssertionError("Partial cold and complete hot source frames differ");});
        game.getInput().setCursorPos(size[0]-20,size[1]/2.);game.waitTicks(2);game.takeScreenshot("hoi-army-theater-template-warning-contract-"+size[0]+"x"+size[1]+"-gui2");
        var summary=game.computeOnClient(client->hit("template_summary",TEMPLATE_ONE));game.getInput().setCursorPos((summary.x()+summary.w()/2.)*2,(summary.y()+summary.h()/2.)*2);game.waitTicks(2);game.takeScreenshot("hoi-army-template-source-tooltip-contract-"+size[0]+"x"+size[1]+"-gui2");
        String blockedReason="§R편제 하나의 편제는 변경할 수 없습니다.§!\n\n§HShift + 클릭§! 원문 보존";var blockedJson=gson.toJsonTree(view).getAsJsonObject();for(var item:blockedJson.getAsJsonArray("cards")){var panel=item.getAsJsonObject().getAsJsonObject("panel");if(panel==null)continue;for(var row:panel.getAsJsonArray("members"))if(row.getAsJsonObject().get("id").getAsString().equals("a1"))row.getAsJsonObject().getAsJsonObject("data").addProperty("templateBlock",blockedReason);}var blockedView=gson.fromJson(blockedJson,View.class);
        game.runOnClient(client->MapCommanderHud.accept(blockedView));game.waitTicks(2);var blocked=game.computeOnClient(client->hit("change_template_button",blockedReason));game.runOnClient(client->{click(blocked,InputConstants.MOUSE_BUTTON_RIGHT);click(blocked,InputConstants.MOUSE_BUTTON_LEFT);click(blocked,InputConstants.MOUSE_BUTTON_LEFT);if(!requests.isEmpty())throw new AssertionError("Mixed locked selection must block requests before opening a picker");});game.getInput().setCursorPos((blocked.x()+blocked.w()/2.)*2,(blocked.y()+blocked.h()/2.)*2);game.waitTicks(2);game.takeScreenshot("hoi-army-template-blocked-contract-"+size[0]+"x"+size[1]+"-gui2");
        game.runOnClient(client->click(hit("template_summary",TEMPLATE_TWO),InputConstants.MOUSE_BUTTON_LEFT));game.waitTicks(2);game.runOnClient(client->{click(hit("change_template_button",null),InputConstants.MOUSE_BUTTON_LEFT);if(!requests.equals(List.of(new Open(Mode.ARMY_TOOLBAR,"DIVISIONS_TEMPLATE",List.of("unit/a2")))))throw new AssertionError("An unselected locked template must not block the selected unlocked division");requests.clear();MapCommanderHud.accept(view);MapCommanderPanels.select("A",false);});game.waitTicks(2);
        game.getInput().holdKey(o->o.keyShift);game.runOnClient(client->click(hit("template_summary",TEMPLATE_ONE),InputConstants.MOUSE_BUTTON_LEFT));game.waitTicks(2);game.runOnClient(client->click(hit("template_summary",TEMPLATE_TWO),InputConstants.MOUSE_BUTTON_LEFT));game.getInput().releaseKey(o->o.keyShift);game.waitTicks(2);
        game.runOnClient(client->{if(!MapUnitHud.selectedKeys().isEmpty())throw new AssertionError("Template toggles must allow zero selected divisions");hit("template_summary",TEMPLATE_ONE);click(hit("change_template_button",null),InputConstants.MOUSE_BUTTON_LEFT);click(hit("nv_btn_delete",null),InputConstants.MOUSE_BUTTON_LEFT);if(!requests.isEmpty())throw new AssertionError("Empty selection must disable template and disband requests");MapCommanderPanels.closeCard(view.cards().stream().filter(c->c.id().equals("A")).findFirst().orElseThrow());});game.waitTicks(2);
        game.runOnClient(client->{if(MapCommanderPanels.hits().stream().anyMatch(h->h.icon().equals("template_summary")))throw new AssertionError("Closing an empty template context must remove its header");MapCommanderPanels.select("A",false);});game.waitTicks(2);
        game.runOnClient(client->{var assign=hit("theater_assign",null);click(assign,InputConstants.MOUSE_BUTTON_RIGHT);click(assign,InputConstants.MOUSE_BUTTON_RIGHT);if(commands.size()!=1||!commands.getFirst().action().equals("FORMATION/THEATER_ASSIGN")||!commands.getFirst().selection().equals(List.of("target/theater/1","A")))throw new AssertionError("Theater right click must send one exact assignment until revision changes");var ctx=MapCommanderOrders.currentContext();MapCommanderOrders.accept(new ProtocolCommanderOrders.Context(ctx.token(),ctx.revision()+1,ctx.country(),ctx.dimension(),""));commands.clear();click(assign,InputConstants.MOUSE_BUTTON_LEFT);if(!MapUnitHud.selectedKeys().equals(Set.of("unit/a1","unit/a2","unit/b1","unit/c1"))||!commands.isEmpty())throw new AssertionError("Theater left click must select its full membership locally");});game.waitTicks(2);
        game.runOnClient(client->{if(MapCommanderPanels.hits().stream().anyMatch(h->h.icon().equals("theater_create")))throw new AssertionError("Selecting complete groups must hide new theater");MapCommanderPanels.select("A",false);});game.waitTicks(2);
        game.runOnClient(client->{var create=hit("theater_create",null);click(create,InputConstants.MOUSE_BUTTON_RIGHT);if(!commands.isEmpty())throw new AssertionError("Theater create right click must issue nothing");click(create,InputConstants.MOUSE_BUTTON_LEFT);if(commands.size()!=1||!commands.getFirst().action().equals("FORMATION/THEATER_CREATE")||!commands.getFirst().selection().equals(List.of("A")))throw new AssertionError("New theater must request the selected grouped army");});
        game.runOnClient(client->MapUnitHud.selectDivisions(List.of(),false));game.waitTicks(2);game.runOnClient(client->{if(MapCommanderPanels.hits().stream().anyMatch(h->h.icon().equals("theater_create")))throw new AssertionError("New theater control must hide without selected formations");});
        var many=new ArrayList<Theater>();for(int n=1;n<=32;n++)many.add(new Theater("theater/"+n,"한국 전구 "+n,0,List.of(),List.of(),Map.of(),List.of(new Control("THEATER_ASSIGN","","전구 "+n,true,new Open(Mode.ARMY_TOOLBAR,"THEATER_ASSIGN")))));
        game.runOnClient(client->MapCommanderHud.accept(new View(view.country(),view.dimension(),view.branch(),view.cards(),view.wings(),true,many)));game.waitTicks(2);
        game.runOnClient(client->{var row=hit("theater_assign","전구 1");for(int n=0;n<200;n++)if(!MapCommanderHud.scrollAt(row.x()+row.w()/2.,row.y()+row.h()/2.,-1))throw new AssertionError("Theater scroll must consume the original panel region");});game.waitTicks(2);
        game.runOnClient(client->{hit("theater_assign","전구 32");if(MapCommanderPanels.hits().stream().anyMatch(h->h.icon().equals("theater_assign")&&h.tip().equals("전구 1")))throw new AssertionError("Clipped theater must not retain an active hit target");});game.getInput().setCursorPos(size[0]-20,size[1]/2.);game.takeScreenshot("hoi-theaters-last-page-contract-"+size[0]+"x"+size[1]+"-gui2");
    }
    private static MapCommanderPanels.Hit hit(String icon,String tip){return MapCommanderPanels.hits().stream().filter(h->h.icon().equals(icon)&&(tip==null||h.tip().equals(tip))).findFirst().orElseThrow(()->new AssertionError("Missing control: "+icon));}
    private static void click(MapCommanderPanels.Hit hit,int button){double x=hit.x()+hit.w()/2.,y=hit.y()+hit.h()/2.;if(!MapCommanderHud.clickAt(x,y,button,false))throw new AssertionError("Control input was not consumed: "+hit.icon());}
}
